import { readFile, writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const input = new URL("../../../docs/api/openapi.json", import.meta.url);
const output = new URL("../src/schema.ts", import.meta.url);
const text =
  "// Generated by pnpm api:generate; do not edit.\n" +
  astToString(await openapiTS(input));
if (process.argv.includes("--check")) {
  if ((await readFile(output, "utf8")) !== text)
    throw new Error("API client is stale. Run pnpm api:generate.");
} else {
  await writeFile(output, text);
}
